async def get_profile_statistics(guild_id: int, user_id: int) -> tuple[int, int, int]:
    """Возвращает количество сообщений, место в топе и голосовой онлайн."""
    now = datetime.now(timezone.utc)

    async with db_lock:
        with db_connect() as connection:
            message_row = connection.execute(
                """
                SELECT count
                FROM message_counts
                WHERE guild_id = ? AND user_id = ?
                """,
                (guild_id, user_id),
            ).fetchone()
            message_count = int(message_row["count"]) if message_row else 0

            rank_row = connection.execute(
                """
                SELECT 1 + COUNT(*) AS position
                FROM message_counts
                WHERE guild_id = ? AND count > ?
                """,
                (guild_id, message_count),
            ).fetchone()
            rank = int(rank_row["position"])

            voice_row = connection.execute(
                """
                SELECT total_seconds, session_started_at
                FROM voice_stats
                WHERE guild_id = ? AND user_id = ?
                """,
                (guild_id, user_id),
            ).fetchone()

    voice_seconds = 0
    if voice_row:
        voice_seconds = int(voice_row["total_seconds"])
        started_at = voice_row["session_started_at"]
        if started_at:
            try:
                started = datetime.fromisoformat(started_at)
                if started.tzinfo is None:
                    started = started.replace(tzinfo=timezone.utc)
                voice_seconds += max(0, int((now - started).total_seconds()))
            except (TypeError, ValueError):
                pass

    return message_count, rank, voice_seconds


async def start_voice_session(guild_id: int, user_id: int) -> None:
    now = datetime.now(timezone.utc).isoformat()
    async with db_lock:
        with db_connect() as connection:
            connection.execute(
                """
                INSERT INTO voice_stats(guild_id, user_id, total_seconds, session_started_at)
                VALUES (?, ?, 0, ?)
                ON CONFLICT(guild_id, user_id) DO UPDATE SET
                    session_started_at = COALESCE(voice_stats.session_started_at, excluded.session_started_at)
                """,
                (guild_id, user_id, now),
            )


async def finish_voice_session(guild_id: int, user_id: int) -> None:
    now = datetime.now(timezone.utc)
    async with db_lock:
        with db_connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            row = connection.execute(
                """
                SELECT total_seconds, session_started_at
                FROM voice_stats
                WHERE guild_id = ? AND user_id = ?
                """,
                (guild_id, user_id),
            ).fetchone()
            if row is None or not row["session_started_at"]:
                connection.commit()
                return

            try:
                started = datetime.fromisoformat(row["session_started_at"])
                if started.tzinfo is None:
                    started = started.replace(tzinfo=timezone.utc)
                elapsed = max(0, int((now - started).total_seconds()))
            except (TypeError, ValueError):
                elapsed = 0

            connection.execute(
                """
                UPDATE voice_stats
                SET total_seconds = total_seconds + ?, session_started_at = NULL
                WHERE guild_id = ? AND user_id = ?
                """,
                (elapsed, guild_id, user_id),
            )
            connection.commit()


async def initialize_active_voice_sessions() -> None:
    for guild in bot.guilds:
        for channel in guild.voice_channels:
            for member in channel.members:
                if not member.bot:
                    await start_voice_session(guild.id, member.id)


async def get_marriage_partner_id(guild_id: int, user_id: int) -> int | None:
    async with db_lock:
        with db_connect() as connection:
            row = connection.execute(
                """
                SELECT user1_id, user2_id
                FROM marriages
                WHERE guild_id = ? AND (user1_id = ? OR user2_id = ?)
                LIMIT 1
                """,
                (guild_id, user_id, user_id),
            ).fetchone()

    if row is None:
        return None
    return int(row["user2_id"] if int(row["user1_id"]) == user_id else row["user1_id"])


async def create_marriage(guild_id: int, user1_id: int, user2_id: int) -> bool:
    """Создаёт брак, если оба пользователя всё ещё свободны."""
    async with db_lock:
        with db_connect() as connection:
            connection.execute("BEGIN IMMEDIATE")
            existing = connection.execute(
                """
                SELECT 1
                FROM marriages
                WHERE guild_id = ?
                  AND (
                      user1_id IN (?, ?)
                      OR user2_id IN (?, ?)
                  )
                LIMIT 1
                """,
                (guild_id, user1_id, user2_id, user1_id, user2_id),
            ).fetchone()

            if existing is not None:
                connection.rollback()
                return False

            connection.execute(
                """
                INSERT INTO marriages(guild_id, user1_id, user2_id, created_at)
                VALUES (?, ?, ?, ?)
                """,
                (
                    guild_id,
                    user1_id,
                    user2_id,
                    datetime.now(timezone.utc).isoformat(),
                ),
            )
            connection.commit()
            return True


async def remove_marriage(guild_id: int, user_id: int) -> int | None:
    """Удаляет брак и возвращает ID бывшего партнёра."""
    async with db_lock:
        with db_connect() as connection:
            row = connection.execute(
                """
                SELECT user1_id, user2_id
                FROM marriages
                WHERE guild_id = ? AND (user1_id = ? OR user2_id = ?)
                LIMIT 1
                """,
                (guild_id, user_id, user_id),
            ).fetchone()
            if row is None:
                return None
            partner_id = int(row["user2_id"] if int(row["user1_id"]) == user_id else row["user1_id"])
            connection.execute(
                "DELETE FROM marriages WHERE guild_id = ? AND (user1_id = ? OR user2_id = ?)",
                (guild_id, user_id, user_id),
            )
            connection.commit()
            return partner_id


# -----------------------------------------------------------------------------
# Вспомогательные функции
# -----------------------------------------------------------------------------

def moscow_time(value: datetime | None = None) -> datetime:
    if value is None:
        value = datetime.now(timezone.utc)
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return value.astimezone(MOSCOW_TZ)


def russian_time(value: datetime | None = None) -> str:
    return moscow_time(value).strftime("Сегодня, в %H:%M")


def discord_full_timestamp(value: datetime | None = None) -> str:
    """Динамическая дата Discord с локальным часовым поясом каждого пользователя."""
    if value is None:
        value = datetime.now(timezone.utc)
    if value.tzinfo is None:
        value = value.replace(tzinfo=timezone.utc)
    return f"<t:{int(value.timestamp())}:F>"


def russian_datetime(value: datetime) -> str:
    months = (
        "января", "февраля", "марта", "апреля", "мая", "июня",
        "июля", "августа", "сентября", "октября", "ноября", "декабря",
    )
    local = moscow_time(value)
    today = moscow_time().date()

    if local.date() == today:
        return local.strftime("Сегодня, в %H:%M")
    if local.date() == today + timedelta(days=1):
        return local.strftime("Завтра, в %H:%M")

    return (
        f"{local.day} {months[local.month - 1]} {local.year}, "
        f"в {local:%H:%M}"
    )


def russian_date(value: datetime) -> str:
    months = (
        "января", "февраля", "марта", "апреля", "мая", "июня",
        "июля", "августа", "сентября", "октября", "ноября", "декабря",
    )
    local = moscow_time(value)
    return f"{local.day} {months[local.month - 1]}, {local.year}"


def avatar_url(user: discord.abc.User) -> str:
    return user.display_avatar.with_size(1024).url


def member_id_text(member: discord.abc.User) -> str:
    return f"{member.mention}\nID: `{member.id}`"


def get_channel(guild: discord.Guild, channel_id: int):
    return guild.get_channel(channel_id)


async def send_economy_log(guild: discord.Guild | None, embed: discord.Embed) -> None:
    """Отправляет лог изменения экономики в отдельный канал."""
    if guild is None:
        return

    channel = guild.get_channel(ECONOMY_LOG_CHANNEL_ID)
    if channel is None:
        try:
            channel = await guild.fetch_channel(ECONOMY_LOG_CHANNEL_ID)
        except (discord.NotFound, discord.Forbidden, discord.HTTPException) as error:
            print(f"Не удалось получить канал логов экономики: {error}")
            return

    if not isinstance(channel, discord.abc.Messageable):
        print(f"Канал {ECONOMY_LOG_CHANNEL_ID} не поддерживает отправку сообщений")
        return

    try:
        await channel.send(embed=embed)
    except (discord.Forbidden, discord.HTTPException) as error:
        print(f"Ошибка отправки лога экономики: {error}")


async def find_audit_entry(
    guild: discord.Guild,
    action: discord.AuditLogAction,
    target_id: int,
    max_age: int = 15,
):
    try:
        async for entry in guild.audit_logs(limit=12, action=action):
            if not entry.target or entry.target.id != target_id:
                continue
            age = (datetime.now(timezone.utc) - entry.created_at).total_seconds()
            if age <= max_age:
                return entry
    except discord.Forbidden:
        print(f"Нет права на просмотр журнала аудита на сервере: {guild.name}")
    except discord.HTTPException as error:
        print(f"Ошибка получения журнала аудита: {error}")
    return None


def format_roles_for_log(roles: list[discord.Role]) -> str:
    value = "> " + " ".join(role.mention for role in roles)
    return value if len(value) <= 1024 else value[:1021] + "..."


def protected_record(guild_id: int, user_id: int) -> list[int] | None:
    with db_connect() as connection:
        row = connection.execute(
            "SELECT saved_role_ids FROM antichrash_members WHERE guild_id = ? AND user_id = ?",
            (guild_id, user_id),
        ).fetchone()
    if row is None:
        return None
    try:
        return [int(role_id) for role_id in json.loads(row["saved_role_ids"])]
    except (TypeError, ValueError, json.JSONDecodeError):
        return []


def save_protected_record(guild_id: int, user_id: int, role_ids: list[int]) -> None:
    with db_connect() as connection:
        connection.execute(
            """
            INSERT INTO antichrash_members(guild_id, user_id, saved_role_ids, activated_at)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(guild_id, user_id)
            DO UPDATE SET saved_role_ids = excluded.saved_role_ids,
                          activated_at = excluded.activated_at
            """,
            (
                guild_id,
                user_id,
                json.dumps(role_ids),
                datetime.now(timezone.utc).isoformat(),
            ),
        )


def remove_protected_record(guild_id: int, user_id: int) -> list[int] | None:
    role_ids = protected_record(guild_id, user_id)
    if role_ids is None:
        return None
    with db_connect() as connection:
        connection.execute(
            "DELETE FROM antichrash_members WHERE guild_id = ? AND user_id = ?",
            (guild_id, user_id),
        )
    return role_ids


