# /give
# -----------------------------------------------------------------------------

class GiveView(discord.ui.View):
    def __init__(self, sender: discord.Member, recipient: discord.Member, amount: int):
        super().__init__(timeout=60)
        self.sender = sender
        self.recipient = recipient
        self.amount = amount
        self.done = False

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.sender.id:
            await interaction.response.send_message("Эти кнопки доступны только автору команды.", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="Подтвердить", style=discord.ButtonStyle.secondary)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self.done:
            await interaction.response.send_message("Операция уже завершена.", ephemeral=True)
            return
        self.done = True
        success, _, _, fee = await transfer_coins(
            self.sender.id,
            self.recipient.id,
            self.amount,
            f"Передано пользователю {self.recipient.id}",
            f"Получено от пользователя {self.sender.id}",
        )
        embed = discord.Embed(title="Передать монеты", color=COLOR)
        embed.set_thumbnail(url=avatar_url(self.sender))
        if success:
            embed.description = (
                f"{self.sender.mention}, Вы передали **{self.amount}** {COIN_EMOJI}\n"
                f"пользователю {self.recipient.mention}"
            )

            log_embed = discord.Embed(title="Передача монет", color=COLOR)
            log_embed.add_field(name="Выдал(а)", value=member_id_text(self.sender), inline=False)
            log_embed.add_field(name="Пользователю", value=member_id_text(self.recipient), inline=False)
            log_embed.add_field(name="Количество монет", value=f"{self.amount} {COIN_EMOJI}", inline=False)
            log_embed.add_field(name="Комиссия", value=f"{fee} {COIN_EMOJI}", inline=False)
            log_embed.add_field(name="Получено пользователем", value=f"{self.amount} {COIN_EMOJI}", inline=False)
            log_embed.add_field(
                name="Списано у отправителя",
                value=f"{self.amount + fee} {COIN_EMOJI}",
                inline=False,
            )
            log_embed.set_footer(text=russian_time())
            await send_economy_log(interaction.guild, log_embed)
        else:
            embed.description = f"{self.sender.mention}, у Вас недостаточно монет с учётом комиссии 5%"
        await interaction.response.edit_message(embed=embed, view=None)

    @discord.ui.button(label="Отмена", style=discord.ButtonStyle.danger)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self.done:
            await interaction.response.send_message("Операция уже завершена.", ephemeral=True)
            return
        self.done = True
        embed = discord.Embed(title="Передать монеты", color=COLOR)
        embed.set_thumbnail(url=avatar_url(self.sender))
        embed.description = (
            f"{self.sender.mention}, вы **отказались** передавать **{self.amount}** {COIN_EMOJI} "
            f"пользователю {self.recipient.mention}"
        )
        await interaction.response.edit_message(embed=embed, view=None)


@bot.tree.command(name="give", description="Передать монеты пользователю")
@app_commands.rename(user="пользователь", amount="количество")
async def give(interaction: discord.Interaction, user: discord.Member, amount: int):
    if amount <= 0:
        await interaction.response.send_message("Количество должно быть больше нуля.", ephemeral=True)
        return
    if user.id == interaction.user.id:
        await interaction.response.send_message("Нельзя передавать монеты самому себе.", ephemeral=True)
        return
    if user.bot:
        await interaction.response.send_message("Нельзя передавать монеты боту.", ephemeral=True)
        return
    fee = max(1, math.ceil(amount * 0.05))
    coins, _ = await get_balance(interaction.user.id)
    if coins < amount + fee:
        await interaction.response.send_message("Недостаточно монет с учётом комиссии 5%.", ephemeral=True)
        return
    embed = discord.Embed(title="Передать монеты", color=COLOR)
    embed.set_thumbnail(url=avatar_url(interaction.user))
    embed.description = (
        f"{interaction.user.mention}, Вы **уверены** что хотите\n"
        f"передать **{amount}** {COIN_EMOJI}, включая\n"
        f"комиссию 5% пользователю {user.mention}?"
    )
    await interaction.response.send_message(embed=embed, view=GiveView(interaction.user, user, amount))


# -----------------------------------------------------------------------------
# /message
# Требуется актуальная версия discord.py из ветки master с поддержкой
# Label, TextDisplay, Select и FileUpload внутри Modal.
# -----------------------------------------------------------------------------

def has_message_role(member: discord.Member) -> bool:
    return any(role.id in MESSAGE_ALLOWED_ROLE_IDS for role in member.roles)


class MessageModal(discord.ui.Modal):
    def __init__(
        self,
        sender: discord.Member,
        recipient: discord.Member,
    ):
        super().__init__(title="Отправить сообщение")
        self.sender = sender
        self.recipient = recipient


        self.message_label = discord.ui.Label(
            text="Сообщение",
            description="До 1000 символов",
            component=discord.ui.TextInput(
                style=discord.TextStyle.paragraph,
                placeholder="Введите сообщение",
                min_length=1,
                max_length=1000,
                required=True,
            ),
        )
        self.add_item(self.message_label)

        self.anonymity_label = discord.ui.Label(
            text="Анонимность",
            description="Выберите один вариант",
            component=discord.ui.Select(
                placeholder="Выберите режим",
                min_values=1,
                max_values=1,
                options=[
                    discord.SelectOption(
                        label="Анонимно",
                        value="anonymous",
                        description="Автор будет скрыт",
                    ),
                    discord.SelectOption(
                        label="От своего имени",
                        value="named",
                        description="Автор не будет скрыт",
                    ),
                ],
            ),
        )
        self.add_item(self.anonymity_label)

        self.image_label = discord.ui.Label(
            text="Изображение (необязательно)",
            description="Можно прикрепить одну картинку",
            component=discord.ui.FileUpload(
                min_values=0,
                max_values=1,
                required=False,
            ),
        )
        self.add_item(self.image_label)

    async def on_submit(self, interaction: discord.Interaction):
        message_input = self.message_label.component
        anonymity_select = self.anonymity_label.component
        image_upload = self.image_label.component

        assert isinstance(message_input, discord.ui.TextInput)
        assert isinstance(anonymity_select, discord.ui.Select)
        assert isinstance(image_upload, discord.ui.FileUpload)

        message_text = message_input.value.strip()
        anonymity = anonymity_select.values[0]
        uploaded_files = image_upload.values

        if not message_text:
            await interaction.response.send_message(
                "Сообщение не может быть пустым.",
                ephemeral=True,
            )
            return

        image = uploaded_files[0] if uploaded_files else None
        if image is not None:
            content_type = image.content_type or ""
            if not content_type.startswith("image/"):
                await interaction.response.send_message(
                    "Можно прикрепить только изображение.",
                    ephemeral=True,
                )
                return

        author_value = (
            "Анонимно"
            if anonymity == "anonymous"
            else self.sender.mention
        )

        quoted_message = "\n".join(
            f"> {line}" if line else ">"
            for line in message_text.splitlines()
        )

        embed = discord.Embed(
            title="Сообщение для вас",
            color=COLOR,
        )
        embed.add_field(
            name="От",
            value=author_value,
            inline=False,
        )
        embed.add_field(
            name="Сообщение",
            value=quoted_message,
            inline=False,
        )

        if image is not None:
            embed.set_image(url=image.url)

        try:
            await self.recipient.send(
                embed=embed,
                allowed_mentions=discord.AllowedMentions.none(),
            )
        except discord.Forbidden:
            await interaction.response.send_message(
                "Не удалось отправить сообщение: у пользователя закрыты личные сообщения.",
                ephemeral=True,
            )
            return
        except discord.HTTPException:
            await interaction.response.send_message(
                "Не удалось отправить сообщение. Попробуйте ещё раз.",
                ephemeral=True,
            )
            return

        await interaction.response.send_message(
            f"Сообщение успешно отправлено пользователю {self.recipient.mention}.",
            ephemeral=True,
            allowed_mentions=discord.AllowedMentions.none(),
        )

    async def on_error(
        self,
        interaction: discord.Interaction,
        error: Exception,
    ):
        print(f"Ошибка формы /message: {error!r}")
        if interaction.response.is_done():
            await interaction.followup.send(
                "Произошла ошибка при отправке сообщения.",
                ephemeral=True,
            )
        else:
            await interaction.response.send_message(
                "Произошла ошибка при отправке сообщения.",
                ephemeral=True,
            )


@bot.tree.command(
    name="message",
    description="Отправить сообщение",
)
@app_commands.describe(user="Пользователь, которому нужно отправить сообщение")
@app_commands.rename(user="пользователь")
async def message(interaction: discord.Interaction, user: discord.Member):
    if not interaction.guild or not isinstance(interaction.user, discord.Member):
        await interaction.response.send_message(
            "Команда доступна только на сервере.",
            ephemeral=True,
        )
        return

    if not has_message_role(interaction.user):
        await interaction.response.send_message(
            "У вас нет доступа к этой команде.",
            ephemeral=True,
        )
        return

    if user.bot:
        await interaction.response.send_message(
            "Нельзя отправить сообщение боту.",
            ephemeral=True,
        )
        return

    await interaction.response.send_modal(
        MessageModal(interaction.user, user)
    )


# -----------------------------------------------------------------------------
# /hide
# -----------------------------------------------------------------------------

def can_hide_role(member: discord.Member, role: discord.Role) -> bool:
    if role.is_default() or role.managed or role.id in {ANTI_CRASH_ROLE_ID, BOOSTER_ROLE_ID}:
        return False
    me = member.guild.me
    return role in member.roles and me is not None and role < me.top_role


async def hide_role_autocomplete(interaction: discord.Interaction, current: str):
    if not isinstance(interaction.user, discord.Member):
        return []
    choices = []
    for role in reversed(interaction.user.roles):
        if can_hide_role(interaction.user, role) and current.lower() in role.name.lower():
            choices.append(app_commands.Choice(name=role.name[:100], value=str(role.id)))
        if len(choices) >= 25:
            break
    return choices


@bot.tree.command(name="hide", description="Спрятать роль")
@app_commands.describe(role="Роль, которую нужно спрятать")
@app_commands.rename(role="роль")
@app_commands.autocomplete(role=hide_role_autocomplete)
async def hide(interaction: discord.Interaction, role: str):
    if not interaction.guild or not isinstance(interaction.user, discord.Member):
        await interaction.response.send_message("Команда доступна только на сервере.", ephemeral=True)
        return
    try:
        role_id = int(role)
    except ValueError:
        await interaction.response.send_message("Выберите роль из списка.", ephemeral=True)
        return
    target_role = interaction.guild.get_role(role_id)
    if target_role is None or not can_hide_role(interaction.user, target_role):
        embed = discord.Embed(title="Спрятать роль", color=COLOR)
        embed.set_thumbnail(url=avatar_url(interaction.user))
        embed.description = f"{interaction.user.mention}, у Вас нет выбранной роли"
        await interaction.response.send_message(embed=embed)
        return
    try:
        await interaction.user.remove_roles(target_role, reason="Пользователь спрятал роль через /hide")
    except (discord.Forbidden, discord.HTTPException):
        await interaction.response.send_message("Не удалось спрятать роль.", ephemeral=True)
        return
    async with db_lock:
        with db_connect() as connection:
            connection.execute(
                """
                INSERT OR REPLACE INTO hidden_roles(guild_id, user_id, role_id, hidden_at)
                VALUES (?, ?, ?, ?)
                """,
                (
                    interaction.guild.id,
                    interaction.user.id,
                    target_role.id,
                    datetime.now(timezone.utc).isoformat(),
                ),
            )
    embed = discord.Embed(title="Спрятать роль", color=COLOR)
    embed.set_thumbnail(url=avatar_url(interaction.user))
    embed.description = f"{interaction.user.mention}, Вы успешно спрятали роль\n{target_role.mention}"
    await interaction.response.send_message(embed=embed)


# -----------------------------------------------------------------------------
# /transactions
# -----------------------------------------------------------------------------

class TransactionsView(discord.ui.View):
    def __init__(self, owner_id: int, user: discord.Member, rows: list[sqlite3.Row]):
        super().__init__(timeout=120)
        self.owner_id = owner_id
        self.user = user
        self.rows = rows
        self.page = 0
        self.per_page = 6
        self.update_buttons()

    @property
    def page_count(self):
        return max(1, math.ceil(len(self.rows) / self.per_page))

    def update_buttons(self):
        self.previous.disabled = self.page <= 0
        self.next.disabled = self.page >= self.page_count - 1

    def build_embed(self):
        start = self.page * self.per_page
        page_rows = self.rows[start:start + self.per_page]
        lines = []

        for row in page_rows:
            amount = int(row["amount"])
            icon = "➕" if amount > 0 else "➖"
            date = russian_date(datetime.fromisoformat(row["created_at"]))

            description = row["description"]

            # Показываем пользователя через @mention
            if "Передано пользователю " in description:
                user_id = description.split("Передано пользователю ")[-1]

                if user_id.isdigit():
                    description = f"Передано пользователю <@{user_id}>"

            # Если есть получение от пользователя
            if "Получено от пользователя " in description:
                user_id = description.split("Получено от пользователя ")[-1]

                if user_id.isdigit():
                    description = f"Получено от пользователя <@{user_id}>"

            lines.append(
                f"{icon} {abs(amount)} [{date}]\n{description}"
            )

        if not lines:
            lines.append("История транзакций отсутствует")

        embed = discord.Embed(
            title=f"Транзакции — {self.user.name}",
            description="\n".join(lines),
            color=COLOR,
        )

        embed.set_thumbnail(url=avatar_url(self.user))
        embed.set_footer(text=f"Страница {self.page + 1}/{self.page_count}")

        return embed

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.owner_id:
            await interaction.response.send_message(
                "Кнопки доступны только автору команды.",
                ephemeral=True
            )
            return False
        return True

    @discord.ui.button(label="◀", style=discord.ButtonStyle.secondary)
    async def previous(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.page -= 1
        self.update_buttons()
        await interaction.response.edit_message(
            embed=self.build_embed(),
            view=self
        )

    @discord.ui.button(label="▶", style=discord.ButtonStyle.secondary)
    async def next(self, interaction: discord.Interaction, button: discord.ui.Button):
        self.page += 1
        self.update_buttons()
        await interaction.response.edit_message(
            embed=self.build_embed(),
            view=self
        )


@bot.tree.command(name="transactions", description="История транзакций")
async def transactions(interaction: discord.Interaction):
    rows = await get_transactions(interaction.user.id)
    view = TransactionsView(interaction.user.id, interaction.user, rows)
    await interaction.response.send_message(
        embed=view.build_embed(),
        view=view
    )

